class Solution:
    def isValid(self, s: str) -> bool:
        if len(s) % 2 == 1:
            return False
        stk = []
        pair = {
            '(': ')',
            '[': ']',
            '{': '}'
        }
        for ch in s:
            if ch in pair:
                stk.append(ch)
            else:
                if stk and pair[stk[-1]] == ch:
                    stk.pop()
                else:
                    return False
        return not stk
